defmodule AtlasGates.MixProject do
  use Mix.Project

  def project do
    [
      app: :atlas_gates,
      version: "0.1.0",
      build_path: "../../_build",
      config_path: "../../config/config.exs",
      deps_path: "../../deps",
      lockfile: "../../mix.lock",
      elixir: "~> 1.18",
      start_permanent: Mix.env() == :prod,
      deps: deps()
    ]
  end

  def application do
    [mod: {AtlasGates.Application, []}, extra_applications: [:logger, :crypto]]
  end

  # Gates reaches the other layers only over the Bus. The gate definitions are data,
  # generated by model/dsl into model/targets/atlas/flows.json and read at compile time.
  defp deps,
    do: [
      {:atlas_bus, in_umbrella: true},
      {:rela_dsl, path: "../../../model/dsl"}
    ]
end
